categories_json=[]
for slug,(name,books) in D.items():
    path=root/'frontend'/'data'/f'{slug}.txt'
    lines=[]
    for title,author,focus,fit in books:
        review=(f"{title} — {author}. Ця книга зосереджується на {focus}. "
                f"Її сила — у поєднанні змістовної теми з виразною авторською оптикою, тому текст не зводиться до простого набору тез. "
                f"Особливо добре вона підійде {fit}.")
        lines.append(review)
    path.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    categories_json.append({'id':slug,'name':name,'file':f'data/{slug}.txt'})
(root/'frontend'/'categories.json').write_text(json.dumps(categories_json,ensure_ascii=False,indent=2),encoding='utf-8')
